case class CelestialBody(name: String, density: Double)
case class NaturalSatellite(name: String, orbit: Double, parentBody: CelestialBody)
def largestNaturalSatelliteByDensity(bodies: List[(CelestialBody, List[NaturalSatellite])]): Option[NaturalSatellite] = {
  bodies.flatMap {
    case (parentBody, satellites) => satellites.map((parentBody, _))
  }.maxByOption {
    case (parentBody, satellite) => parentBody.density * satellite.orbit * satellite.orbit
  }.map(_._2)
}
