    slideSurface = IMG_Load("slide3.png");
    if (slideSurface == NULL) {
        cout << "Unable to load image! SDL Error: " << SDL_GetError() << endl;
        success = false;
    }
    else {
        SDL_Texture* slideTexture = SDL_CreateTextureFromSurface(gRenderer, slideSurface);
        gSlides.push_back(slideTexture);
        gSlideTexts.push_back("Robotics Applications");
        SDL_FreeSurface(slideSurface);
    }
    return success;
}
void close()
{
    for (int i = 0; i < gSlides.size(); i++) {
        SDL_DestroyTexture(gSlides[i]);
    }
    gSlides.clear();
    gSlideTexts.clear();
    SDL_DestroyRenderer(gRenderer);
    SDL_DestroyWindow(gWindow);
    gWindow = NULL;
    gRenderer = NULL;
    IMG_Quit();
    SDL_Quit();
}
void renderSlide()
{
    SDL_RenderClear(gRenderer);
    SDL_RenderCopy(gRenderer, gSlides[gCurrentSlide], NULL, NULL);
    SDL_Color textColor = { 0, 0, 0 };
    SDL_Surface* textSurface = TTF_RenderText_Solid(font, gSlideTexts[gCurrentSlide].c_str(), textColor);
    SDL_Texture* textTexture = SDL_CreateTextureFromSurface(gRenderer, textSurface);
    SDL_Rect textRect = { 10, SCREEN_HEIGHT - 50, textSurface->w, textSurface->h };
    SDL_RenderCopy(gRenderer, textTexture, NULL, &textRect);
    SDL_FreeSurface(textSurface);
    SDL_DestroyTexture(textTexture);
    SDL_RenderPresent(gRenderer);
}
int main(int argc, char* args[])
{
    if (!init()) {
        cout << "Failed to initialize!" << endl;
        return -1;
    }
    if (!loadMedia()) {
        cout << "Failed to load media!" << endl;
        return -1;
    }
    bool quit = false;
    SDL_Event e;
    while (!quit) {
        while (SDL_PollEvent(&e) != 0) {
            if (e.type == SDL_QUIT) {
                quit = true;
            }
            else if (e.type == SDL_KEYDOWN) {
                switch (e.key.keysym.sym) {
                case SDLK_LEFT:
