```
import java.util.Random;
import java.util.Set;
import java.util.HashSet;
import com.atilika.kuromoji.ipadic.Token;
import com.atilika.kuromoji.ipadic.Tokenizer;
public class HaikuGenerator {
    public static void main(String[] args) {
        String[] season = {"Spring", "Summer", "Autumn", "Winter"};
        String[] naturalScene = {"Cherry blossoms", "Beach waves", "Fall leaves", "Snowy mountains"};
        String[] emotion = {"Serene", "Joyful", "Melancholic", "Peaceful"};

        Random random = new Random();
        Set<Integer> usedIndices = new HashSet<>();

        int seasonIndex = getRandomIndex(random, usedIndices, season.length);
        int sceneIndex = getRandomIndex(random, usedIndices, naturalScene.length);
        int emotionIndex = getRandomIndex(random, usedIndices, emotion.length);

        String seasonWord = season[seasonIndex];
        String sceneWord = naturalScene[sceneIndex];
        String emotionWord = emotion[emotionIndex];

        int seasonSyllables = countSyllables(seasonWord);
        int sceneSyllables = countSyllables(sceneWord);
        int emotionSyllables = countSyllables(emotionWord);

        System.out.println(seasonWord + " " + sceneWord + " (" + seasonSyllables + ", " + sceneSyllables + ")");
        System.out.println(emotionWord + " and calm (" + emotionSyllables + ")");
        System.out.println("Nature's beauty abounds (5)");
    }

    public static int countSyllables(String word) {
        Tokenizer tokenizer = new Tokenizer();
        int count = 0;
        for (Token token : tokenizer.tokenize(word)) {
            count += token.getAllFeaturesArray()[0].split("-").length;
        }
        return count;
    }

    public static int getRandomIndex(Random random, Set<Integer> usedIndices, int arrayLength) {
        int index;
        do {
            index = random.nextInt(arrayLength);
        } while (usedIndices.contains(index));
        usedIndices.add(index);
        return index;
    }
}
```
