```
class Student:
    def __init__(self, name, success_score):
        self.name = name
        self.success_score = success_score
class Classroom:
    def __init__(self, students):
        self.students = students
    def average_success_score(self):
        total_success_score = sum(student.success_score for student in self.students)
        return total_success_score / len(self.students)
    def generate_study_plan(self):
        average_score = self.average_success_score()
        study_plan = {}
        for student in self.students:
            if student.success_score < average_score:
                study_hours = round((average_score - student.success_score) * 2)
                study_plan[student.name] = study_hours
        return study_plan
    def generate_game_points(self):
        game_points = {}
        for student in self.students:
            if student.success_score >= 90:
                game_points[student.name] = 100
            elif student.success_score >= 80:
                game_points[student.name] = 75
            elif student.success_score >= 70:
                game_points[student.name] = 50
            else:
                game_points[student.name] = 25
        return game_points
