How can I use HTML and JavaScript to create a file organizing tool that groups files by their attributes and sorts them accordingly? 
Here's an example HTML code for the user interface:
```html
<label for="directory">Select a directory to organize:</label>
<input type="file" id="directory" webkitdirectory mozdirectory>
<br>
<button onclick="organize()">Organize Files</button>
```
And here's an example JavaScript code that uses Node.js to read the files in the selected directory, group them by file type, and sort them by creation date:
```javascript
function organize() {
  const files = document.getElementById("directory").files;
  const fs = require('fs');
  let fileTypes = {};

  for (let i = 0; i < files.length; i++) {
    const file = files[i];
    const fileType = file.type.split('/')[0];
    const fileDate = fs.statSync(file.path).birthtime;

    if (!fileTypes[fileType]) {
      fileTypes[fileType] = [];
    }

    fileTypes[fileType].push({ name: file.name, path: file.path, date: fileDate });
  }

  for (let type in fileTypes) {
    fileTypes[type].sort((a, b) => {
      return a.date - b.date;
    });

    const typeFolder = type + ' Files';

    if (!fs.existsSync(typeFolder)) {
      fs.mkdirSync(typeFolder);
    }

    for (let i = 0; i < fileTypes[type].length; i++) {
      const file = fileTypes[type][i];
      const newPath = typeFolder + '/' + file.name;

      fs.renameSync(file.path, newPath);
    }
  }
}
```
This code reads the files in the selected directory, groups them by their file type, and sorts them by creation date. It then creates a new folder for each file type and moves the files to their respective folders. You can customize this code to group files by other attributes like file size or modification date.

