avg_flood_prone_population = sum(flood_prone_population) / len(flood_prone_population)
# Identify the top five challenges for each country based on their individual data
challenges = {}
for d in data['top_10_emitters']:
    country = d['country']
    emissions = d['emissions']
    temperature_increase = next(item['temperature_increase'] for item in data['temperature_increase'] if item['country'] == country)
    disasters = next(item['disasters'] for item in data['natural_disasters'] if item['country'] == country)
    flood_prone_percentage = next(item['percentage'] for item in data['flood_prone_population'] if item['country'] == country)

    challenges[country] = {
        'emissions': emissions,
        'temperature_increase': temperature_increase,
        'disasters': disasters,
        'flood_prone_percentage': flood_prone_percentage
    }
# Sort the challenges by emissions in descending order
