3. Calculate the projection of u onto W using the standard inner product.
```
double[] projection = new double[3];
for (int i = 0; i < W.GetLength(0); i++)
{
    double dotProduct = 0;
    double normSquared = 0;
    for (int j = 0; j < W.GetLength(1); j++)
    {
        dotProduct += W[i, j] * u[j];
        normSquared += W[i, j] * W[i, j];
    }
    projection[0] += dotProduct / normSquared * W[i, 0];
    projection[1] += dotProduct / normSquared * W[i, 1];
    projection[2] += dotProduct / normSquared * W[i, 2];
}
```
