How can I enhance the functionality of an HTML page with a form that allows users to input a quadratic equation in standard form (e.g. y = 2x^2 + 6x + 5) and convert it to vertex form using JavaScript code? In addition to the current implementation, how can I incorporate a feature that allows users to input a range of values for x, and output a corresponding range of y values? Is there a way to optimize the JavaScript code to handle edge cases, such as when the coefficient of x^2 is zero or negative? Here's an example of what the enhanced HTML page might look like:
<!DOCTYPE html>
<html>
<head>
	<title>Quadratic Equation Converter</title>
</head>
<body>
	<h1>Convert a Quadratic Equation from Standard to Vertex Form</h1>
	<form>
		<label for="a">Coefficient of x^2:</label>
		<input type="number" id="a" name="a"><br><br>
		<label for="b">Coefficient of x:</label>
		<input type="number" id="b" name="b"><br><br>
		<label for="c">Constant:</label>
		<input type="number" id="c" name="c"><br><br>
		<label for="xstart">Starting value of x:</label>
		<input type="number" id="xstart" name="xstart"><br><br>
		<label for="xend">Ending value of x:</label>
		<input type="number" id="xend" name="xend"><br><br>
		<label for="xstep">Step size:</label>
		<input type="number" id="xstep" name="xstep" value="1"><br><br>
		<input type="button" value="Convert Equation" onclick="convertEquation()">
	</form>
	<br>
	<table id="outputTable">
		<tr>
			<th>x</th>
			<th>y</th>
		</tr>
	</table>
	<script>
		function convertEquation() {
			var a = document.getElementById("a").value;
			var b = document.getElementById("b").value;
			var c = document.getElementById("c").value;
			var xStart = document.getElementById("xstart").value;
			var xEnd = document.getElementById("xend").value;
			var xStep = document.getElementById("xstep").value;
			var vertexForm, xVertex, yVertex, yValue;
			var outputTable = document.getElementById("outputTable");
			while (outputTable.rows.length > 1) {
				outputTable.deleteRow(1);
			}
			if (a == 0) {
				vertexForm = "y = " + b + "x + " + c;
				yValue = b * xStart + c;
				addRowToTable(xStart, yValue);
			} else {
				xVertex = -b / (2 * a);
				yVertex = a * xVertex * xVertex + b * xVertex + c;
				vertexForm = "y = " + a + " * (x - " + xVertex.toFixed(2) + ")^2 + " + yVertex.toFixed(2);
				for (var x = xStart; x <= xEnd; x += xStep) {
					yValue = a * (x - xVertex) * (x - xVertex) + yVertex;
					addRowToTable(x, yValue);
				}
			}
			document.getElementById("vertexForm").innerHTML = vertexForm;
		}
		function addRowToTable(x, y) {
			var newRow = document.getElementById("outputTable").insertRow();
			var xCell = newRow.insertCell();
			xCell.appendChild(document.createTextNode(x));
			var yCell = newRow.insertCell();
			yCell.appendChild(document.createTextNode(y.toFixed(2)));
		}
	</script>
</body>
</html>
