{
    animals = (Animal[])serializer.Deserialize(reader);
}
foreach (Animal animal in animals)
{
    Console.WriteLine(animal.Name + " is " + animal.Age + " years old.");
    if (animal is Mammal)
    {
        Mammal mammal = (Mammal)animal;
