    }

    public String toString() {
        return name + "\n" + description + "\n" + dueDate.format(DateTimeFormatter.ISO_LOCAL_DATE) + "\n" + priority + "\n";
    }

    public static void main(String[] args) {
        List<Task> tasks = new ArrayList<>();
        tasks.add(new Task("Finish project", "Complete all remaining tasks for project", LocalDate.parse("2022-08-31"), "High"));
        tasks.add(new Task("Call doctor", "Schedule annual check-up", LocalDate.parse("2022-10-15"), "Medium"));
        tasks.add(new Task("Buy groceries", "Get food for the week", LocalDate.parse("2022-09-01"), "Low"));
        Collections.sort(tasks, (t1, t2) -> t1.getDueDate().compareTo(t2.getDueDate()));
        for (Task task : tasks) {
            System.out.println(task.toString());
